const $=id=>document.getElementById(id);
let catalog, current='8x', runtime, mesh, busy=false, token=0;
const labels={'1x':'Full resolution','2x':'2× downsample','4x':'4× downsample','8x':'8× downsample','8x_component_2':'8× · separate component 2'};
function preset(i){if(!runtime)return;const v=catalog[current].views[i],{camera,controls,THREE}=runtime;camera.position.fromArray(v.position);camera.up.fromArray(v.up);camera.fov=v.fov;camera.updateProjectionMatrix();controls.target.copy(camera.position).add(new THREE.Vector3(...v.forward).multiplyScalar(Math.max(.1,catalog[current].radius*.3)));controls.update();}
function select(){token++;current=$('gs-model').value;if(mesh){runtime.scene.remove(mesh);mesh.dispose();mesh=null;}const m=catalog[current];$('gs-size').textContent=`${m.count.toLocaleString()} Gaussians · ${(m.bytes/1e6).toFixed(1)} MB · all trained Gaussians retained`;$('gs-load').textContent='Load interactive 3D';$('gs-load').disabled=false;$('gs-state').textContent='Choose a rendered view below, or load the model to explore freely.';$('gs-images').replaceChildren(...m.views.map((v,i)=>{const f=document.createElement('figure'),a=document.createElement('a'),img=document.createElement('img'),caption=document.createElement('figcaption'),b=document.createElement('button');a.href=v.render;a.target='_blank';a.rel='noopener';img.src=v.render;img.alt=`${labels[current]} reconstructed view from ${v.frame}`;img.loading='lazy';a.append(img);caption.textContent=v.frame+' · full trained appearance';b.textContent='Go to this camera';b.type='button';b.onclick=async()=>{if(!mesh)await load();preset(i)};f.append(a,caption,b);return f}));}
async function initialize(){if(runtime)return;const THREE=await import('three'),{SparkRenderer,SplatMesh}=await import('./vendor/spark.module.js'),{OrbitControls}=await import('./vendor/OrbitControls.js');const host=$('gs-canvas');let renderer;try{renderer=new THREE.WebGLRenderer({antialias:false,alpha:false});}catch(e){throw Error('Interactive 3D needs WebGL2. Open this site in Chrome or Edge with graphics acceleration enabled. The rendered views below work here.');}renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));host.replaceChildren(renderer.domElement);const scene=new THREE.Scene();scene.background=new THREE.Color('#18232c');const camera=new THREE.PerspectiveCamera(60,1,.01,1000);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;scene.add(new SparkRenderer({renderer}));const resize=()=>{renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(host);resize();renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera)});runtime={THREE,SplatMesh,scene,camera,controls,renderer};}
async function load(){if(busy)return;busy=true;const ticket=token,m=catalog[current];$('gs-load').disabled=true;try{await initialize();if(mesh){runtime.scene.remove(mesh);mesh.dispose();mesh=null;}let offset=0;const bytes=new Uint8Array(m.bytes);for(let i=0;i<m.chunks.length;i++){if(ticket!==token)return;$('gs-state').textContent=`Loading ${labels[current]}: part ${i+1} of ${m.chunks.length}…`;const r=await fetch(m.chunks[i]);if(!r.ok)throw Error('Model download failed. Try loading again.');const a=new Uint8Array(await r.arrayBuffer());bytes.set(a,offset);offset+=a.length;}if(ticket!==token)return;if(offset!==m.bytes)throw Error('Incomplete model download.');$('gs-state').textContent='Preparing Gaussian renderer…';const next=new runtime.SplatMesh({fileBytes:bytes,fileName:'model.splat'});await next.initialized;if(ticket!==token){next.dispose();return;}mesh=next;runtime.scene.add(mesh);preset(0);$('gs-state').textContent=`${labels[current]} loaded. Drag to orbit, right-drag to pan, scroll/pinch to zoom.`;$('gs-load').textContent='Reload model';}catch(e){$('gs-state').textContent=e.message;}finally{busy=false;$('gs-load').disabled=false;}}
$('gs-load').onclick=load;$('gs-model').onchange=select;$('gs-reset').onclick=()=>preset(0);$('gs-fullscreen').onclick=()=>{const el=$('gs-canvas');if(el.requestFullscreen)el.requestFullscreen().catch(()=>{});};
fetch('gaussians/index.json').then(r=>{if(!r.ok)throw Error('Model catalog unavailable');return r.json()}).then(d=>{catalog=d;select()}).catch(e=>{$('gs-state').textContent=e.message});
